import React from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div className="chart-embed">
        <div style={{
          padding: '20px',
          backgroundColor: '#f8f9fa',
          borderRadius: '8px',
          textAlign: 'center',
          minHeight: '350px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center'
        }}>
          <div style={{ fontSize: '2.5em', color: '#14C4B5', fontWeight: 'bold', marginBottom: '10px' }}>
            ₹24,180.50
          </div>
          <div style={{ fontSize: '1.1em', color: '#6c757d', marginBottom: '20px' }}>
            NIFTY 50 Index
          </div>
          <div style={{ fontSize: '0.95em', color: '#28a745' }}>
            +2.5% Today
          </div>
          <p style={{ color: '#6c757d', marginTop: '20px', fontSize: '0.85em' }}>
            Live market data integration available via TradingView API
          </p>
        </div>
      </div>
    </div>
  );
};

export default NiftyChart;
